import matplotlib.pyplot as plt
import pandas as pd
import numpy as np
from sklearn.metrics import roc_curve, auc

# Sample data
data = {
    '29 050': [458, 0, 88, 87, 0, 367],
    '42 331': [555, 0, 88, 87, 0, 270],
}

categories = ['True Negative', 'True Positive', 'Rejected Positive', 'False Negative', 'False Positive', 'Rejected Negative']
df = pd.DataFrame(data, index=categories)
df_percent = df.div(df.sum(axis=0), axis=1) * 100


category_colors = {
    'True Negative': "#f50c0c",      
    'True Positive': '#2ca02c',      
    'Rejected Positive': "#21d8e9",  
    'False Negative': "#f6f22f",    
    'False Positive': "#362de6",     
    'Rejected Negative': "#c750f6"  
}

fig, ax = plt.subplots(figsize=(8, 6))
bottom = np.zeros(len(df.columns))

split_positions = []

for idx in df.index:
    values = df_percent.loc[idx]
    ax.bar(df.columns,
           values,
           bottom=bottom,
           label=idx,
           color=category_colors[idx])

    for i, (value, btm) in enumerate(zip(values, bottom)):
        if value > 3:
            ax.text(i,
                    btm + value / 2,
                    f'{value:.1f}%',
                    ha='center',
                    va='center',
                    fontsize=12,
                    color='black')
    if idx == "Rejected Positive":
        split_positions = bottom + values
    bottom += values

for i, split in enumerate(split_positions):
    ax.hlines(split, i - 0.4, i + 0.4, color='black', linewidth=2.5)

for i, col in enumerate(df.columns):
    bottom_half = df_percent.loc[['True Negative', 'True Positive', 'Rejected Positive'], col].sum()
    top_half = df_percent.loc[['False Negative', 'False Positive', 'Rejected Negative'], col].sum()
    ax.text(i, -4, f'Correct: {bottom_half:.1f}%', 
            ha='center', va='top', fontsize=12, color='black')

ax.set_ylabel("Percentage")
ax.set_xlabel("Sample count")
plt.ylim(-10, 100)  
plt.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
plt.tight_layout()
plt.show()



